  if(['export-paper','export-ink','export-gallery','export-flip'].some(id=>!s.exportTemplates.some(t=>t.id===id))){for(const t of builtinExportTemplates())if(!s.exportTemplates.some(x=>x.id===t.id))s.exportTemplates.unshift(t)}
