function trimUntouchedDemoBook(book,isOriginalDemoPage){if(!book||book.curatedDemo!==true||book.demoContentRevision===2||!Array.isArray(book.steps))return false;if(book.steps.length<2){book.demoContentRevision=2;return false}if(!book.steps.slice(1).every(step=>isOriginalDemoPage(step)))return false;const first=book.steps.find(s=>s.stepIndex===0);if(!first)return false;book.steps=[first];book.totalSteps=1;book.generatedSteps=first.image?1:0;book.status=first.image?'complete':'canceled';book.demoContentRevision=2;book.updatedAt=Date.now();return true}


function originalDemoPage(step){
  if(!step||step.stepIndex<1||step.stepIndex>11||!String(step.image||'').startsWith('data:image/svg+xml'))return false;
  const i=step.stepIndex,expected=[3,4,6,7,9,11].includes(i)?scenicDemoFrame(i,i+42):svgArt(i===8?1:0,100+i);if(step.image!==expected||step.critique)return false;
  const names=['风起的日常','未署名的来信','决定出发','通往海岸的小路','第一个线索','旅途中的同行者','走错的方向','风雨将至','独自做出的选择','灯光下的答案','终于重逢','风抵达的地方'];
  const captions=['夏日的风经过窗边，故事还没有名字。','七海 Nanami收到一封没有署名的信，信纸上留着海的气息。','有些答案，需要亲自走到远方。','小路穿过山野，通向记忆里的海岸。','旧车站的钟，停在我们约定的时刻。','她遇见一位旅人，也听见了一段熟悉的往事。','错过的岔路，原来也有自己的风景。','云层渐渐聚拢，风替她收起了迟疑。','这一次，七海 Nanami决定不再等待。','远处的灯光亮起，信里的一切终于有了答案。','那个熟悉的身影，仍站在夏日的光里。','我们把重逢写进风里，下一段故事从这里开始。'];
  const shots=['a quiet seaside town, distant train tracks, calm summer morning','holding an old letter, close portrait, delicate eyes','standing at an open station gate, a journey begins','cinematic wide landscape, mountain path above the sea','an abandoned train platform, warm faded signs','two travelers meeting by a harbor, soft light','a fork in a green mountain path, reflective atmosphere','wind rises over the coast, dramatic soft clouds','determined expression, wind in hair, dramatic composition','warm lantern at a seaside station, dusk','a quiet reunion, silhouette in warm sunset','ocean horizon, gentle wind, hopeful ending'];
  const prompt='七海 Nanami, white shirt, navy skirt, small canvas bag, cinematic anime illustration, delicate cel shading, soft film texture, a quiet coastal town in summer, '+shots[i];
  return step.name===names[i]&&step.caption===captions[i]&&step.prompt===prompt;
}


function ensureCollectionDisplay(s=state){
  s.settings.presentation??={};const p=s.settings.presentation;
  if(!p.homeLayout){try{p.homeLayout=localStorage.getItem('cc-home-layout')||'showcase'}catch(e){p.homeLayout='showcase'}}p.homeLayout=displayModel.mode(p.homeLayout);
  if(!['spread','webtoon','gallery'].includes(p.defaultReaderMode))p.defaultReaderMode='webtoon';
  p.language=p.language==='en'?'en':p.language==='zh-CN'?'zh-CN':rememberedInterfaceLanguage();
  if(!p.lettering){try{p.lettering=localStorage.getItem('cc-lettering')||'editorial'}catch(e){p.lettering='editorial'}}if(!['editorial','calligraphy','classic'].includes(p.lettering))p.lettering='editorial';
  if(p.demoCleanupVersion!==2){let removed=false;for(const b of s.books||[])if((b.id==='edition_letter'||String(b.id).startsWith('edition_letter_demo_'))&&b.curatedDemo&&!b.inProgress)removed=trimUntouchedDemoBook(b,originalDemoPage)||removed;p.demoCleanupVersion=2;if(removed&&s===state)displayUI.cleanupPending=true}
  return s;
}


